const Q=window.QUESTIONS,E=RadioEngine,C=Combat,$=s=>document.querySelector(s);let state=E.fresh(),audio,mode='order',topic='all',screenMode='start',toastTimer;
try{const raw=localStorage.getItem(E.KEY);if(raw)state=E.validate(JSON.parse(raw),Q);}catch(e){$('#savewarn').hidden=false;}
state.world=C.valid(state.world)?state.world:C.fresh();mode=state.playMode||'order';topic=state.playTopic||'all';
const topics={all:'All topics',T1:'Rules & licenses',T2:'Operating',T3:'Radio waves',T4:'Station setup',T5:'Electricity',T6:'Circuits',T7:'Troubleshooting',T8:'Signals',T9:'Antennas',T0:'Safety'};
const names=['Sunrise Island','Crystal Coast','Echo Forest','Aurora Outpost','Storm Ridge'];
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function save(){try{localStorage.setItem(E.KEY,JSON.stringify(state));$('#savewarn').hidden=true;}catch(e){$('#savewarn').hidden=false;}}
function unlock(){if(!state.sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume().catch(()=>{});}catch(e){}}
function sfx(type){if(!state.sound)return;unlock();if(!audio)return;let notes=({shot:[880,440],hit:[150,90],right:[523,659,784,1047],wrong:[300,220],win:[392,523,659,784,1047],heal:[440,660],step:[]})[type]||[660];notes.forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+i*(type==='shot'?.03:.09);o.type=type==='hit'?'triangle':'sine';o.frequency.setValueAtTime(f,t);o.frequency.exponentialRampToValueAtTime(f*.65,t+.12);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(type==='shot'?.04:.07,t+.005);g.gain.exponentialRampToValueAtTime(.0001,t+.17);o.connect(g).connect(audio.destination);o.start(t);o.stop(t+.18);});}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600);}
function hud(){const w=state.world;$('#hp').textContent=Math.ceil(w.hp);$('#hpbar').style.width=w.hp+'%';$('#hpbar').style.background=w.hp<30?'#ff9d85':'#bdfa79';$('#ammo').textContent=w.ammo;$('#zone').textContent=String(w.level).padStart(2,'0')+' · '+names[(w.level-1)%names.length].toUpperCase();$('#wave').textContent=w.kills+' / '+w.target+' robots disabled';$('#objective').textContent=w.cleared?'Island secured!':'Defeat the rogue robots';$('#hint').textContent=w.ammo===0?'Out of shots! Tap HEAL + RELOAD to answer a question.':w.hp<35?'Low health! Answer a question to recover.':'Move to dodge robots. Hold FIRE to shoot the nearest one.';$('#sound').textContent=state.sound?'♫':'♪';$('#sound').setAttribute('aria-label',state.sound?'Mute sound':'Enable sound');}
function overlay(html,type){Game.running=false;Game.input.x=Game.input.z=0;Game.input.fire=false;screenMode=type;$('#overlay').hidden=false;$('#panel').innerHTML=html;$('#panel').scrollTop=0;}
function play(){unlock();if(!Game.ready){toast('The island is still loading. Try again in a moment.');return;}state.world.started=true;if(state.world.cleared){victory();return;}if(state.world.hp<=0){question();return;}state.world.questionOpen=false;$('#overlay').hidden=true;Game.running=true;screenMode='play';save();hud();}
function selectors(){return `<div class="loadout"><label>Question mode<select id="mode"><option value="order" ${mode==='order'?'selected':''}>Campaign · in order</option><option value="random" ${mode==='random'?'selected':''}>Random signals</option><option value="retry" ${mode==='retry'?'selected':''}>Retry missed (${state.missed.length})</option></select></label><label>Topic<select id="topic">${Object.entries(topics).map(([k,v])=>`<option value="${k}" ${k===topic?'selected':''}>${v}</option>`).join('')}</select></label></div>`;}
function bindSelect(){for(const id of ['mode','topic'])$('#'+id).onchange=()=>{mode=$('#mode').value;topic=$('#topic').value;state.playMode=mode;state.playTopic=topic;save();};}
function start(){overlay(`<div class="eyebrow">RADIO QUEST · ISLAND DEFENDER</div><h1>A little hero.<br>A robot invasion.</h1><p>Explore the island, dodge rogue robots, and use your radio knowledge to power your blaster.</p><div class="rules"><div><b>✥</b>Walk with the joystick or WASD.</div><div><b>◎</b>Hold FIRE. Your blaster aims at nearby robots.</div><div><b>⌁</b>Correct answer = +35 health and +8 shots.</div></div>${selectors()}<button class="primary" id="start">${state.world.started?'Continue island '+state.world.level:'Enter the island'} →</button><p class="fine">409 official questions · Sound on after your tap · Saved on this device</p>`,'start');bindSelect();$('#start').onclick=()=>{unlock();if(state.world.questionOpen)question();else play();};}
function chooseQuestion(){let a=state.session;const compatible=a&&a.mode===mode&&a.topic===topic&&a.index<a.ids.length;if(!compatible){if(!E.start(state,Q,mode,topic)){mode='random';state.playMode=mode;E.start(state,Q,mode,topic);toast('No missed questions here. A random signal is ready.');}}return Q.find(q=>q.id===state.session.ids[state.session.index]);}
function question(){unlock();const q=chooseQuestion(),a=state.session,selected=a.selected,answered=selected!==null,ok=answered&&selected===q.answer;state.world.questionOpen=true;save();const figure=q.question.match(/figure (T-\d)/i);overlay(`<div class="panel-top"><span class="eyebrow">${state.world.hp<=0?'RESCUE SIGNAL':'RADIO RECHARGE'}</span>${state.world.hp>0?'<button class="close" id="close-question" aria-label="Back to battle">×</button>':''}</div><p class="fine">Battle paused · Correct answer restores 35 HP + 8 shots</p><div class="question-meta">${q.id} · ${topics[q.id.slice(0,2)]}</div><h2 id="qtitle">${esc(q.question)}</h2>${figure?`<a class="figure" href="figure-${figure[1].toUpperCase()}.png" target="_blank" rel="noopener"><img src="figure-${figure[1].toUpperCase()}.png" alt="Official circuit figure ${figure[1]}"><small>Tap to open full size</small></a>`:''}<div class="answers" role="group" aria-labelledby="qtitle">${q.options.map((o,i)=>`<button class="answer ${answered?(i===q.answer?'correct':i===selected?'wrong':''):''}" data-answer="${i}" ${answered?'disabled':''}><b>${answered&&i===q.answer?'✓':'ABCD'[i]}</b><span>${esc(o)}</span></button>`).join('')}</div>${answered?`<div class="feedback ${ok?'':'wrong'}" role="status"><strong>${ok?'Power restored!':'Signal missed. Try another.'}</strong><p>${ok?'Your hero is healed and the blaster is charged.':'Correct answer: '+ 'ABCD'[q.answer]+'. '+esc(q.options[q.answer])+' — saved for a retry.'}</p><button class="primary" id="back-battle">${state.world.hp<=0?'Try a recovery question':ok?'Back to battle →':'Continue →'}</button><button class="secondary" id="another">${ok?'Answer another · more health + shots':'Retry this question'}</button></div>`:''}`,'question');
if($('#close-question'))$('#close-question').onclick=()=>{if(answered){E.next(state);}play();};document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const r=E.answer(state,Q,Number(b.dataset.answer));if(!r)return;if(r.ok){C.reward(state.world);Game.healBurst=true;}save();hud();sfx(r.ok?'right':'wrong');question();$('.feedback')?.scrollIntoView({block:'nearest'});});if(answered){$('#back-battle').onclick=()=>{E.next(state);save();if(state.world.hp<=0)question();else play();};$('#another').onclick=()=>{if(ok)E.next(state);else{state.session={mode,topic,ids:[q.id],index:0,selected:null,correct:0,earned:0};}save();question();};}}
function victory(){sfx('win');overlay(`<div class="big-icon">✦</div><div class="eyebrow">ISLAND SECURED</div><h1>You stopped the invasion!</h1><p>The radio tower is safe. A new robot squad is approaching the next island.</p><div class="score-row"><div><strong>${state.world.kills}</strong><span>robots disabled</span></div><div><strong>${state.xp}</strong><span>study XP</span></div><div><strong>${state.world.totalKills}</strong><span>total victories</span></div></div><button class="primary" id="next-island">Next island →</button><button class="secondary" id="rest">Pause at base</button>`,'win');$('#next-island').onclick=()=>{C.next(state.world);Game.rebuild=true;save();play();};$('#rest').onclick=pause;}
function pause(){save();overlay(`<div class="panel-top"><h2>Safe at base</h2><button class="close" id="close-pause" aria-label="Continue game">×</button></div><p>Island ${state.world.level} · ${state.world.totalKills} robots disabled · ${state.xp} XP</p>${selectors()}<button class="primary" id="continue">Continue adventure →</button><button class="secondary" id="repair">Repair bay · ${state.missed.length} missed questions</button><button class="secondary" id="export">Download progress backup</button><label class="secondary file-label">Restore backup<input class="file-input" type="file" id="import" accept=".json,application/json"></label><p class="fine">Saved in this browser. Clearing website data removes progress. Use a backup to transfer between iPhone and iPad. Your original study progress is retained.</p><details><summary>Question source</summary><p class="fine">409 questions and official answer keys from your 2026–2030 Technician public release, February 19, 2026 errata. Includes all three circuit diagrams. This is practice, not an official exam.</p></details>`,'pause');bindSelect();$('#continue').onclick=$('#close-pause').onclick=play;$('#repair').onclick=()=>{if(!state.missed.length){toast('No missed signals. Try a recharge question!');return;}mode='retry';topic='all';state.playMode=mode;state.playTopic=topic;question();};$('#export').onclick=()=>{save();const url=URL.createObjectURL(new Blob([JSON.stringify(state)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='radio-quest-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);};$('#import').onchange=async e=>{try{const f=e.target.files[0];if(!f||f.size>2000000)throw Error();const s=E.validate(JSON.parse(await f.text()),Q);if(s.world&&!C.valid(s.world))throw Error();if(!confirm('Replace current progress with this backup?'))return;state=s;state.world??=C.fresh();Game.rebuild=true;save();hud();start();toast('Progress restored.');}catch(err){toast('Choose a valid Radio Quest backup.');}};}
window.Game={running:false,ready:false,input:{x:0,z:0,fire:false},get world(){return state.world;},save,hud,sfx,question,victory,toast,healBurst:false,rebuild:false};
$('#charge').onclick=question;$('#pause').onclick=()=>{unlock();pause();};$('#sound').onclick=()=>{state.sound=!state.sound;save();hud();if(state.sound)sfx('heal');};let pid=null;const joy=$('#joystick'),stick=$('#stick');joy.onpointerdown=e=>{unlock();pid=e.pointerId;joy.setPointerCapture(pid);move(e);};function move(e){if(e.pointerId!==pid)return;const r=joy.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dz=e.clientY-r.top-r.height/2,len=Math.hypot(dx,dz),scale=Math.min(1,36/Math.max(1,len));Game.input.x=dx*scale/36;Game.input.z=dz*scale/36;stick.style.transform=`translate(${dx*scale}px,${dz*scale}px)`;}joy.onpointermove=move;joy.onpointerup=joy.onpointercancel=()=>{pid=null;Game.input.x=Game.input.z=0;stick.style.transform='';};const fire=$('#fire');fire.onpointerdown=e=>{unlock();fire.setPointerCapture(e.pointerId);Game.input.fire=true;fire.classList.add('firing');};fire.onpointerup=fire.onpointercancel=()=>{Game.input.fire=false;fire.classList.remove('firing');};addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden){Game.running=false;Game.input.fire=false;Game.input.x=Game.input.z=0;save();audio?.suspend();if(screenMode==='play')pause();}});addEventListener('keydown',e=>{if(e.code==='KeyE'&&Game.running){e.preventDefault();question();}if(e.code==='KeyP'&&Game.running){e.preventDefault();pause();}});hud();start();
